begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.k(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.k(n),'core-execution-'||n||'@example.test','{}' from generate_series(1,4)n;
insert into public.organizations(id,name,created_by) values(pg_temp.k(10),'Execution Alpha',pg_temp.k(1)),(pg_temp.k(11),'Execution Beta',pg_temp.k(4));
insert into public.memberships(organization_id,user_id,role) values(pg_temp.k(10),pg_temp.k(1),'OWNER'),(pg_temp.k(10),pg_temp.k(2),'MEMBER'),(pg_temp.k(10),pg_temp.k(3),'VIEWER'),(pg_temp.k(11),pg_temp.k(4),'OWNER');
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
insert into public.tasks(id,organization_id,title,created_by,updated_by) select pg_temp.k(n),pg_temp.k(10),'Execution task '||n,pg_temp.k(1),pg_temp.k(1) from generate_series(20,23)n;
select set_config('request.jwt.claim.sub',pg_temp.k(4)::text,true);
insert into public.tasks(id,organization_id,title,created_by,updated_by) values(pg_temp.k(24),pg_temp.k(11),'Foreign private task',pg_temp.k(4),pg_temp.k(4));
select public.save_milestone(pg_temp.k(11),pg_temp.k(31),'Foreign checkpoint','',null,'ACTIVE',null,false,null);
select public.save_core_note(pg_temp.k(11),pg_temp.k(41),'Foreign working note','Private synthetic body',false,null);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select lives_ok($$select public.save_milestone(pg_temp.k(10),pg_temp.k(30),'Private beta','A delivery checkpoint',current_date+7,'ACTIVE',pg_temp.k(2),false,null)$$,'editor creates a minimal Milestone');
select lives_ok($$select public.set_task_milestone(pg_temp.k(10),pg_temp.k(20),pg_temp.k(30))$$,'Task has one explicit Milestone');
select is((select milestone_id from public.tasks where id=pg_temp.k(20)),pg_temp.k(30),'association persists');
select throws_ok($$select public.set_task_milestone(pg_temp.k(10),pg_temp.k(20),pg_temp.k(31))$$,'42501',null,'foreign Milestone denied');
select throws_ok($$select public.set_task_milestone(pg_temp.k(10),pg_temp.k(24),pg_temp.k(30))$$,'42501',null,'foreign Task denied');
select lives_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(20),pg_temp.k(21),true)$$,'add prerequisite');
select throws_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(20),pg_temp.k(21),true)$$,'23505',null,'duplicate prerequisite rejected');
select throws_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(20),pg_temp.k(20),true)$$,'22023',null,'self prerequisite rejected');
select throws_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(20),pg_temp.k(24),true)$$,'42501',null,'foreign prerequisite rejected');
select lives_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(21),pg_temp.k(22),true)$$,'chain is explicit');
select throws_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(22),pg_temp.k(20),true)$$,'22023',null,'transitive cycle rejected');
select is((select blocked_count from public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(20)])),1,'blocked state derived from unresolved prerequisites');
update public.tasks set status='COMPLETED',updated_by=pg_temp.k(1) where id=pg_temp.k(21);
select is((select blocked_count from public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(20)])),0,'completion unblocks dependent');
select is((select status::text from public.tasks where id=pg_temp.k(20)),'TODO','dependent is never completed automatically');
update public.tasks set status='CANCELLED',updated_by=pg_temp.k(1) where id=pg_temp.k(21);
select is((select blocked_count from public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(20)])),1,'cancelled prerequisite is unresolved, not falsely completed');
select lives_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(20),pg_temp.k(21),false)$$,'remove prerequisite');
select is((select blocked_count from public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(20)])),0,'removed prerequisite no longer blocks');
select is((select count(*)::integer from public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(24)])),0,'batched reads reveal no foreign Task');
select throws_ok($$select public.task_execution_summaries(pg_temp.k(10),array_fill(pg_temp.k(20),array[1001]))$$,'22023',null,'summary batches are bounded');
select lives_ok($$select public.set_task_milestone(pg_temp.k(10),pg_temp.k(22),pg_temp.k(30))$$,'second Task joins checkpoint');
update public.tasks set status='COMPLETED',updated_by=pg_temp.k(1) where id=pg_temp.k(20);
select is((select completed_count from public.milestone_progress(pg_temp.k(10),array[pg_temp.k(30)])),1,'real completed count');
select is((select total_count from public.milestone_progress(pg_temp.k(10),array[pg_temp.k(30)])),2,'real associated task total');
select is((select status from public.milestones where id=pg_temp.k(30)),'ACTIVE','Task completion does not change Milestone status');
select lives_ok($$select public.save_milestone(pg_temp.k(10),pg_temp.k(30),'Private beta','Reviewed checkpoint',current_date+9,'COMPLETE',pg_temp.k(2),true,(select updated_at from public.milestones where id=pg_temp.k(30)))$$,'edit and archive retain checkpoint history');
select throws_ok($$select public.set_task_milestone(pg_temp.k(10),pg_temp.k(23),pg_temp.k(30))$$,'42501',null,'new association to archived checkpoint denied');
select is((select milestone_title from public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(20)])),'Private beta','existing archived checkpoint stays honestly inspectable');
select lives_ok($$select public.save_core_note(pg_temp.k(10),pg_temp.k(40),'Launch retrospective','# Working note
No automatic durable Knowledge.',false,null)$$,'create Core working Note');
select is((select count(*)::integer from public.knowledge_memories),0,'Task/Milestone/Note mutations create no Memory');
select lives_ok($$select public.set_core_note_link(pg_temp.k(10),pg_temp.k(40),'task',pg_temp.k(20),true)$$,'Note links canonical Task');
select lives_ok($$select public.set_core_note_link(pg_temp.k(10),pg_temp.k(40),'task',pg_temp.k(20),true)$$,'duplicate Note link is idempotent');
select is((select count(*)::integer from public.note_links),1,'one link, not duplicated work');
select throws_ok($$select public.set_core_note_link(pg_temp.k(10),pg_temp.k(40),'task',pg_temp.k(24),true)$$,'42501',null,'foreign Task link denied');
select throws_ok($$select public.set_core_note_link(pg_temp.k(10),pg_temp.k(41),'task',pg_temp.k(20),true)$$,'42501',null,'foreign Note mutation denied');
select throws_ok($$select public.set_core_note_link(pg_temp.k(10),pg_temp.k(40),'milestone',pg_temp.k(31),true)$$,'42501',null,'foreign Note/Milestone relation denied');
select throws_ok($$select public.set_core_note_link(pg_temp.k(10),pg_temp.k(40),'marketing-private',pg_temp.k(20),true)$$,'42501',null,'no universal polymorphic private-domain write');
select throws_ok($$select public.save_core_note(pg_temp.k(10),pg_temp.k(40),'Old editor','Stale',false,null)$$,'PT409',null,'stale Note edit cannot overwrite');
select throws_ok($$select public.promote_core_note(pg_temp.k(10),pg_temp.k(40),'INSIGHT','Stale review','Unreviewed changed source','2000-01-01')$$,'PT409',null,'promotion binds to the exact reviewed Note revision');
select lives_ok($$select public.promote_core_note(pg_temp.k(10),pg_temp.k(40),'INSIGHT','Explicit reviewed insight','Reviewed durable excerpt only',(select updated_at from public.notes where id=pg_temp.k(40)))$$,'separate explicit promotion uses public company-memory contract');
select lives_ok($$select public.promote_core_note(pg_temp.k(10),pg_temp.k(40),'FACT','Retry must not overwrite','Changed retry',(select updated_at from public.notes where id=pg_temp.k(40)))$$,'promotion retry reuses canonical Memory');
select is((select count(*)::integer from public.knowledge_memories),1,'one Memory per Note');
select is((select title from public.knowledge_memories),'Explicit reviewed insight','retry never overwrites');
select is((select domain::text||':'||provenance::text from public.knowledge_memories),'company:HUMAN','promotion stays human company-domain data');
select ok((select source_reference like '%'||pg_temp.k(40)::text||'%' from public.knowledge_memories),'Memory records exact Note provenance');
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select lives_ok($$select public.save_core_note(pg_temp.k(10),pg_temp.k(40),'Edited working note','Human working material remains editable',false,(select updated_at from public.notes where id=pg_temp.k(40)))$$,'MEMBER collaborates on working Note');
select is((select content from public.knowledge_memories),'Reviewed durable excerpt only','later Note edits do not rewrite permanent Knowledge');
select lives_ok($$select public.save_core_note(pg_temp.k(10),pg_temp.k(40),'Edited working note','Retained text',true,(select updated_at from public.notes where id=pg_temp.k(40)))$$,'archive Note without deleting content/history');
select throws_ok($$select public.promote_core_note(pg_temp.k(10),pg_temp.k(40),'NOTE','Archived','No new promotion',(select updated_at from public.notes where id=pg_temp.k(40)))$$,'42501',null,'archived Note cannot be promoted anew');
select set_config('request.jwt.claim.sub',pg_temp.k(3)::text,true);
select is((select count(*)::integer from public.notes),1,'VIEWER reads own organization, never foreign Note');
select is((select count(*)::integer from public.milestones),1,'VIEWER reads own checkpoint only');
select throws_ok($$select public.save_core_note(pg_temp.k(10),pg_temp.k(50),'Denied','Viewer mutation',false,null)$$,'42501',null,'VIEWER Note write denied');
select throws_ok($$select public.save_milestone(pg_temp.k(10),pg_temp.k(51),'Denied','',null,'PLANNED',null,false,null)$$,'42501',null,'VIEWER Milestone write denied');
select throws_ok($$select public.set_task_dependency(pg_temp.k(10),pg_temp.k(20),pg_temp.k(23),true)$$,'42501',null,'VIEWER dependency mutation denied');
select throws_ok($$select public.set_task_milestone(pg_temp.k(10),pg_temp.k(23),null)$$,'42501',null,'VIEWER assignment denied');
select throws_ok($$select public.promote_core_note(pg_temp.k(10),pg_temp.k(40),'NOTE','Denied','Viewer promotion',(select updated_at from public.notes where id=pg_temp.k(40)))$$,'42501',null,'VIEWER promotion denied');
select throws_ok($$insert into public.task_dependencies(organization_id,task_id,blocked_by_id,created_by) values(pg_temp.k(10),pg_temp.k(20),pg_temp.k(23),pg_temp.k(3))$$,'42501',null,'direct dependency writes cannot bypass cycle validation');
select throws_ok($$update public.notes set title='Bypass' where id=pg_temp.k(40)$$,'42501',null,'direct Note writes denied');
reset role;
update public.memberships set removed_at=clock_timestamp() where organization_id=pg_temp.k(10) and user_id=pg_temp.k(2);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select is((select count(*)::integer from public.notes),0,'revoked member loses Note reads');
select throws_ok($$select public.task_execution_summaries(pg_temp.k(10),array[pg_temp.k(20)])$$,'42501',null,'revoked member loses summary authority');
select throws_ok($$select public.save_core_note(pg_temp.k(10),pg_temp.k(50),'Denied','Revoked',false,null)$$,'42501',null,'revoked member cannot mutate');
reset role;
select ok(not pg_catalog.has_table_privilege('anon','public.notes','SELECT'),'anonymous Note reads denied');
select ok(not pg_catalog.has_function_privilege('anon','public.set_task_dependency(uuid,uuid,uuid,boolean)','EXECUTE'),'anonymous dependency execution denied');
select ok(not pg_catalog.has_function_privilege('authenticated','private.require_execution_editor(uuid)','EXECUTE'),'private authority helper not browser executable');
select * from finish();
rollback;
